mapper.select:
SELECT prc.`id`, prc.`record_code`, prc.`person_name`, prc.`index_code`, prc.`face_photo`, prc.`capture_photo`, prc.`device_code`, prc.`task_type`, prc.`similarity`, prc.`status`, prc.`remark`, prc.`rollcall_time`, prc.`area_index_code`, prc.`department_index_code`, prc.`department_name`, prc.`device_name`, prc.`area_name`, prc.`third_record_id`, prc.`deleted`, prc.`tenant`, prc.`create_by`, prc.`create_time`, prc.`update_by`, prc.`update_time` FROM `person_roll_call` prc
prc.`deleted` = 0
AND prc.`record_code` = #{param.recordCode}
AND prc.`person_name` LIKE CONCAT('%', #{param.personName}, '%')
AND prc.`index_code` = #{param.indexCode}
AND prc.`status` = #{param.status}
AND prc.`device_name` LIKE CONCAT('%', #{param.deviceName}, '%')
AND prc.`area_name` LIKE CONCAT('%', #{param.areaName}, '%')
ORDER BY prc.`create_time` DESC

