prc.`deleted` = 0
AND prc.`record_code` = #{param.recordCode}
AND prc.`person_name` LIKE CONCAT('%', #{param.personName}, '%')
AND prc.`index_code` = #{param.indexCode}
AND prc.`status` = #{param.status}
AND prc.`device_name` LIKE CONCAT('%', #{param.deviceName}, '%')
